void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy; // Normalize pixel coordinates

    // Parameters
    float blurSize = 0.005;            // Size of the blur
    int samples = 16;                  // Number of blur samples
    float distortionStrength = 0.02;  // Strength of distortion effect

    // Rectangle size
    vec2 rectSize = vec2(0.5, 0.5); // Width and height of the rectangle

    // Movement parameters
    vec2 rectSpeed = vec2(0.05, 0.05); // Speed of movement (units per second)
    vec2 rectCenter = vec2(0.5) + sin(iTime * rectSpeed * 6.28318) * 0.5; // Oscillates within bounds

    // Calculate rectangle bounds
    vec2 rectMin = rectCenter - 0.5 * rectSize;
    vec2 rectMax = rectCenter + 0.5 * rectSize;

    // Check if the current pixel is inside the rectangle
    if (uv.x > rectMin.x && uv.x < rectMax.x && uv.y > rectMin.y && uv.y < rectMax.y) {
        // Map UV to rectangle's local space (0 to 1 range within the rectangle)
        vec2 localUV = (uv - rectMin) / rectSize;

        // Fetch distortion offsets from the noise texture (relative to the rectangle)
        vec2 noise = texture(iChannel1, localUV).rg * 2.0 - 1.0; // Map [0,1] to [-1,1]
        noise *= vec2(1.0, 0.8); // Adjust aspect ratio for noise distortion
        vec2 distortedUV = uv + distortionStrength * noise;

        // Initialize color accumulator
        vec3 color = vec3(0.0);

        // Perform a circular blur sampling
        for (int i = 0; i < samples; i++) {
            float angle = float(i) / float(samples) * 6.28318; // Full circle (2*PI)
            vec2 offset = vec2(cos(angle), sin(angle)) * blurSize;
            color += texture(iChannel0, distortedUV + offset).rgb;
        }

        // Average the accumulated colors
        color /= float(samples);

        // Output frosted glass color
        fragColor = vec4(color, 1.0);
    } else {
        // Outside the frosted glass rectangle: pass the original texture
        fragColor = texture(iChannel0, uv);
    }
}
